byte i;          
byte LedMin = 2;  
byte LedMax = 4; 

void setup() {

   for(i=LedMin; i<=LedMax; i++) { pinMode(i, OUTPUT); }
}

void loop() {

   for(i=LedMin; i<=LedMax; i++) {
      digitalWrite(i, HIGH);
      delay(50);
   }


   for(i=LedMax; i>=LedMin; i--) {
      digitalWrite(i, LOW);
      delay(50);
   }
}
